// A modeling tool button that is greyed out (with the reason on hover) until the
// selection it works on is there, instead of a button that silently does nothing.
static bool ToolButton(const char* label, bool ok, const char* why, bool small = false) {
    ImGui::BeginDisabled(!ok);
    const bool hit = small ? ImGui::SmallButton(label) : ImGui::Button(label);
    ImGui::EndDisabled();
    if (!ok && ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled)) ImGui::SetTooltip("%s", why);
    return hit && ok;
}
static const char* const kNeedFaces = "Select faces first: Face mode (key 3), then click faces in the 3D view.";
static const char* const kNeedVerts = "Select vertices first: Vertex mode (key 1), then click vertices in the 3D view.";
static const char* const kNeedEdges = "Select edges first: Edge mode (key 2), then click edges in the 3D view.";

// Load the renderer's mesh file (.okaymesh or .obj) into it.
static void LoadMeshFileInto(EditorState& ed, MeshRenderer* mr) {
    Mesh m; std::string tex, err;
    if (okay::modeling::LoadMeshAsset(mr->meshPath, m, &tex, &err)) {
        ed.PushUndo();
        mr->mesh = m;
        mr->meshPathHash = okay::modeling::GeometryHash(mr->mesh);
        if (!tex.empty() && mr->texture.empty()) mr->texture = tex;
        ConsoleLog("Loaded " + mr->meshPath + " (" + std::to_string(mr->mesh.TriangleCount()) + " triangles)");
        ed.dirty = true;
    } else {
        ConsoleLog("Couldn't load the mesh file: " + err, 2);
    }
}

// "Save as Mesh Asset": write the object's mesh to <project>/Assets/<name>.okaymesh
// (quads kept as quads) and point the object at it, so other objects and scenes
// can use the same model. Saving the scene later writes edits back to the file.
static void SaveMeshAssetButton(EditorState& ed, GameObject* go, MeshRenderer* mr) {
    const bool isAsset = okay::modeling::IsOkayMeshPath(mr->meshPath);
    if (ImGui::Button(isAsset ? "Save Mesh Asset##meshasset" : "Save as Mesh Asset##meshasset")) {
        std::filesystem::path path;
        if (isAsset) path = mr->meshPath;
        else {
            // The project's Assets folder; without a project, next to the open scene.
            std::filesystem::path dir = !ed.projectDir().empty() ? std::filesystem::path(ed.projectDir()) / "Assets"
                                      : !ed.path().empty() ? std::filesystem::path(ed.path()).parent_path()
                                      : std::filesystem::current_path();
            std::string base;
            for (char c : go->name) base += (std::isalnum((unsigned char)c) || c == '-' || c == '_') ? c : '_';
            if (base.empty()) base = "Mesh";
            path = dir / (base + ".okaymesh");
            for (int n = 2; std::filesystem::exists(path); ++n) path = dir / (base + "_" + std::to_string(n) + ".okaymesh");
        }
        std::error_code ec;
        if (path.has_parent_path()) std::filesystem::create_directories(path.parent_path(), ec);
        std::string err;
        if (okay::modeling::SaveMeshAsset(path.string(), mr->mesh, &err)) {
            if (!isAsset) ed.PushUndo();
            mr->meshPath = path.string();
            mr->meshPathHash = okay::modeling::GeometryHash(mr->mesh);
            ed.dirty = true;
            okay::modeling::PolyMesh pm;
            okay::modeling::PolyMesh::Load(path.string(), pm);
            ConsoleLog("Saved mesh asset " + path.string() + " (" + std::to_string(pm.faces.size()) + " faces: " +
                       std::to_string(pm.CountFaces(4)) + " quads, " + std::to_string(pm.CountFaces(3)) + " triangles, " +
                       std::to_string(pm.CountNgons()) + " n-gons)");
        } else {
            ConsoleLog("Couldn't save the mesh asset: " + err, 2);
        }
    }
    if (ImGui::IsItemHovered())
        ImGui::SetTooltip(isAsset ? "Write this mesh back to %s now (saving the scene does it too)."
                                  : "Save this mesh as a .okaymesh file in the project's Assets folder and use it from there,\nso other objects and scenes can share the model. Quads are kept as quads.",
                          mr->meshPath.c_str());
}

// ---- Undo inside mesh edit mode -------------------------------------------
// Each edit-mode step stores a copy of just that mesh (and the selection), not
// a text snapshot of the whole scene, so undo stays instant on big meshes.
// Leaving edit mode turns the whole session into one scene undo step.
struct MeshUndoStep {
    Mesh mesh;
    std::vector<int> verts, faces;
    std::vector<std::pair<int, int>> edges;
};
std::vector<MeshUndoStep> g_meshUndo, g_meshRedo;
Mesh g_meshEditStart;            // the mesh as it was when edit mode began
bool g_meshEditStartSet = false;
static MeshUndoStep MeshUndoCapture(const Mesh& m) { return {m, g_meshSelVerts, g_meshSelFaces, g_meshSelEdges}; }
static void MeshUndoRestore(Mesh& m, MeshUndoStep& s) {
    m = std::move(s.mesh);
    g_meshSelVerts = std::move(s.verts); g_meshSelFaces = std::move(s.faces); g_meshSelEdges = std::move(s.edges);
}
static MeshRenderer* EditedRenderer() { return g_meshEdit && g_meshEditObj ? g_meshEditObj->GetComponent<MeshRenderer>() : nullptr; }
// Call before changing a mesh: one undo step. In edit mode on this mesh it's a
// mesh step; otherwise an ordinary scene undo step.
static void EditUndoPoint(EditorState& ed, MeshRenderer* mr) {
    if (!mr || mr != EditedRenderer()) { ed.PushUndo(); return; }
    g_meshUndo.push_back(MeshUndoCapture(mr->mesh));
    g_meshRedo.clear();
    // Keep it bounded: at most 100 steps and about 4 million stored vertices.
    std::size_t total = 0;
    for (const auto& s : g_meshUndo) total += s.mesh.vertices.size();
    while (g_meshUndo.size() > 1 && (g_meshUndo.size() > 100 || total > 4000000)) {
        total -= g_meshUndo.front().mesh.vertices.size();
        g_meshUndo.erase(g_meshUndo.begin());
    }
}
// Ctrl+Z / Ctrl+Y in edit mode. Returns false when there's no mesh step to take
// (then the ordinary scene undo applies).
static bool MeshUndo(bool redo) {
    MeshRenderer* mr = EditedRenderer();
    auto& from = redo ? g_meshRedo : g_meshUndo;
    auto& to = redo ? g_meshUndo : g_meshRedo;
    if (!mr || from.empty()) return false;
    to.push_back(MeshUndoCapture(mr->mesh));
    MeshUndoRestore(mr->mesh, from.back());
    from.pop_back();
    return true;
}
// Leaving edit mode: if the mesh changed, record the whole session as one scene
// undo step (the scene snapshot taken with the mesh as it was on entry).
static void MeshUndoCommit(EditorState& ed) {
    MeshRenderer* mr = EditedRenderer();
    if (mr && g_meshEditStartSet &&
        okay::modeling::GeometryHash(mr->mesh) != okay::modeling::GeometryHash(g_meshEditStart)) {
        Mesh now = mr->mesh;
        mr->mesh = g_meshEditStart;
        ed.PushUndo();
        mr->mesh = std::move(now);
    }
    g_meshUndo.clear(); g_meshRedo.clear();
    g_meshEditStart = Mesh{}; g_meshEditStartSet = false;
}

// ---- The polygon view of the mesh being edited --------------------------
// Picking, the wireframe and the edge-loop tools work on real polygons (quads,
// n-gons). The mesh's polyFace says which triangles make each one; it's kept
// up to date here, so a tool that rebuilt the triangles still hands back clean
// polygons (found from the triangles) and every tool sees the faces you see.
struct EditPolyCache {
    std::uint64_t key = 0;
    okay::modeling::PolyMesh pm;
    std::vector<std::pair<int, int>> edges;
};
static EditPolyCache g_editPoly;
// Only the topology: moving vertices doesn't change the polygons.
static std::uint64_t PolyTopologyKey(const Mesh& m) {
    std::uint64_t h = 1469598103934665603ull;
    auto mix = [&](const void* d, std::size_t n) {
        const unsigned char* p = static_cast<const unsigned char*>(d);
        for (std::size_t i = 0; i < n; ++i) { h ^= p[i]; h *= 1099511628211ull; }
    };
    const std::size_t counts[3] = {m.vertices.size(), m.triangles.size(), m.polyFace.size()};
    mix(counts, sizeof(counts));
    const Mesh* self = &m;   // two meshes with the same triangles are still two meshes
    mix(&self, sizeof(self));
    if (!m.triangles.empty()) mix(m.triangles.data(), m.triangles.size() * sizeof(int));
    if (!m.polyFace.empty()) mix(m.polyFace.data(), m.polyFace.size() * sizeof(int));
    return h;
}
static const okay::modeling::PolyMesh& EditPoly(Mesh& m) {
    if (PolyTopologyKey(m) != g_editPoly.key) {
        std::vector<int> map;
        g_editPoly.pm = okay::modeling::PolyMesh::FromMesh(m, {false, true, 1.0f}, &map);
        if (map != m.polyFace) m.polyFace = map;
        g_editPoly.edges.clear();
        for (const auto& e : g_editPoly.pm.Edges()) g_editPoly.edges.push_back({e.a, e.b});
        g_editPoly.key = PolyTopologyKey(m);
    }
    return g_editPoly.pm;
}
static const std::vector<std::pair<int, int>>& EditPolyEdges(Mesh& m) { EditPoly(m); return g_editPoly.edges; }

// Run a polygon tool on the edited mesh as one undo step: the triangles are
// rebuilt, vertices no face uses any more are dropped and the selection is
// remapped. `op` returns false to leave the mesh as it was. `undo` = false for
// a live preview (the caller handles undo).
static bool ApplyPoly(EditorState& ed, MeshRenderer* mr, const std::function<bool(okay::modeling::PolyMesh&)>& op, bool undo = true) {
    if (!mr) return false;
    okay::modeling::PolyMesh pm = okay::modeling::PolyMesh::FromMesh(mr->mesh, {false, true, 1.0f});
    const std::vector<MeshUndoStep> redoKept = undo ? g_meshRedo : std::vector<MeshUndoStep>{};
    if (undo) EditUndoPoint(ed, mr);   // before op: it may set the new selection
    if (!op(pm)) {
        if (undo && mr == EditedRenderer() && !g_meshUndo.empty()) {
            MeshUndoRestore(mr->mesh, g_meshUndo.back());   // nothing changed: give the step back
            g_meshUndo.pop_back();
            g_meshRedo = redoKept;
        }
        return false;
    }
    const std::vector<int> remap = okay::modeling::CompactVerts(pm);
    const bool smooth = mr->mesh.HasNormals();
    const float autoAngle = mr->mesh.autoSmoothAngle;
    // Keep the welded vertices (and exact per-corner UVs) the edit works on.
    Mesh out = pm.ToMesh(nullptr, mr != EditedRenderer());
    out.name = "";
    if (smooth) { if (autoAngle > 0.0f) out.ComputeAutoSmoothNormals(autoAngle); else out.ComputeSmoothNormals(); }
    mr->mesh = std::move(out);
    auto rv = [&](int v) { return v >= 0 && v < (int)remap.size() ? remap[v] : -1; };
    std::vector<int> verts;
    for (int v : g_meshSelVerts) if (rv(v) >= 0) verts.push_back(rv(v));
    std::vector<std::pair<int, int>> edges;
    for (const auto& e : g_meshSelEdges) if (rv(e.first) >= 0 && rv(e.second) >= 0) edges.push_back({rv(e.first), rv(e.second)});
    g_meshSelVerts = std::move(verts);
    g_meshSelEdges = std::move(edges);
    g_meshSelFaces.clear();
    ed.dirty = true;
    return true;
}

// The selected edges, or (vertex / face mode) the edges between selected
// vertices / around the selected faces, as polygon edges.
static okay::modeling::EdgeList SelectedPolyEdges(Mesh& m) {
    okay::modeling::EdgeList out;
    if (g_meshSelMode == 2) return g_meshSelEdges;
    std::set<int> vs;
    if (g_meshSelMode == 0) vs.insert(g_meshSelVerts.begin(), g_meshSelVerts.end());
    else for (int f : g_meshSelFaces) if (f >= 0 && f < m.TriangleCount()) for (int k = 0; k < 3; ++k) vs.insert(m.triangles[f * 3 + k]);
    for (const auto& e : EditPolyEdges(m)) if (vs.count(e.first) && vs.count(e.second)) out.push_back(e);
    return out;
}

// Stop whatever edge-loop tool is running. A bevel preview is undone; a slide
// keeps where it got to.
static void EndPolyTool(bool keep) {
    MeshRenderer* mr = EditedRenderer();
    if (g_ptool == PolyTool::Bevel && mr && !keep) {
        mr->mesh = g_bevelStart;
        g_meshSelVerts = g_bevelSelVerts; g_meshSelFaces = g_bevelSelFaces; g_meshSelEdges = g_bevelSelEdges;
    }
    if (g_ptool == PolyTool::Slide && mr && !keep && g_slideFrom.size() == mr->mesh.vertices.size()) mr->mesh.vertices = g_slideFrom;
    g_ptool = PolyTool::None;
    g_ptoolTyped.Clear();
    g_knifePts.clear(); g_knifePos.clear();
    g_slideLoop.clear(); g_slideFrom.clear();
    g_slideAfterCut = false;
}

// Enter or leave mesh edit mode on `go` (the panel's Edit Mesh checkbox and Tab).
static void SetMeshEditMode(EditorState& ed, GameObject* go, bool on) {
    if (g_meModal.Active() && g_meModalObj) {   // never leave a transform half done
        bool alive = false;   // (an undo may have rebuilt the scene under it)
        for (const auto& up : ed.scene().Objects()) if (up.get() == g_meModalObj) { alive = true; break; }
        if (auto* mr = alive ? g_meModalObj->GetComponent<MeshRenderer>() : nullptr) g_meModal.Cancel(mr->mesh);
        else g_meModal.Confirm();
        g_meModalObj = nullptr;
    }
    if (g_ptool != PolyTool::None) {   // a bevel / slide / knife half done: put it back
        bool alive = false;
        for (const auto& up : ed.scene().Objects()) if (up.get() == g_meshEditObj) { alive = true; break; }
        if (alive) EndPolyTool(false); else g_ptool = PolyTool::None;
    }
    if (g_meshEdit && g_meshEditObj) {   // finishing an edit session: one scene undo step for it
        bool alive = false;
        for (const auto& up : ed.scene().Objects()) if (up.get() == g_meshEditObj) { alive = true; break; }
        if (alive) MeshUndoCommit(ed);
        // Back to the drawable form: split at the UV seams (vertex numbers kept).
        if (auto* emr = alive ? g_meshEditObj->GetComponent<MeshRenderer>() : nullptr)
            if (emr->mesh.HasCornerUVs()) emr->mesh = emr->mesh.SplitCornerUVs();
    }
    g_meshUndo.clear(); g_meshRedo.clear(); g_meshEditStartSet = false;
    MeshRenderer* mr = go ? go->GetComponent<MeshRenderer>() : nullptr;
    if (on && mr) {
        g_meshEditStart = mr->mesh;   // before the weld, so undoing the session gives back the original
        g_meshEditStartSet = true;
        // Weld first so a primitive (24-vert cube) becomes clean shared
        // topology (8 verts), then moving a vertex moves the whole corner. The
        // UVs move onto the triangle corners first, so UV seams survive the weld.
        mr->mesh.CaptureCornerUVs();
        mr->mesh.WeldVertices();
        g_meshEdit = true; g_meshEditObj = go; g_meshEditObjName = go->name;
        g_meshSculpt = false; ed.dirty = true;
    } else {
        g_meshEdit = false; g_meshEditObj = nullptr;
    }
    g_meshSelVerts.clear(); g_meshSelFaces.clear(); g_meshSelEdges.clear();
}
