int   g_colliderDragAxis = -1;        // 0=X 1=Y 2=Z, -1 = none held
int   g_colliderDragSign = 1;         // which face (+1 or -1 along the axis)
GameObject* g_uiDragTarget = nullptr; // UI widget being dragged in the viewport
