                if (ImGui::DragFloat2("##mxy", xy, 0.05f)) { m.threshold = xy[0]; m.posY = xy[1]; ed.dirty = true; }
                ImGui::SameLine();
                if (ImGui::SmallButton("x")) delM = mi;
