            if (ImGui::InputText("##pn", pb, sizeof(pb))) { p.name = pb; ed.dirty = true; }
            ImGui::SameLine(); ImGui::SetNextItemWidth(70);
            if (ImGui::Combo("##pt", &p.type, kPTypes, 4)) ed.dirty = true;
