                std::string joined;   // frames as "a.png, b.png" (empty = use the atlas row)
                for (const auto& f : cl.frames) joined += (joined.empty() ? "" : ", ") + f;
                char fb[512]; std::strncpy(fb, joined.c_str(), sizeof(fb) - 1); fb[sizeof(fb) - 1] = '\0';
